import { useMemo, type ReactNode } from "react";
import { createConnectTransport } from "@connectrpc/connect-web";
import { Stigmer } from "@stigmer/sdk";
import { StigmerProvider } from "@stigmer/react";

interface PreviewProvidersProps {
  readonly children: ReactNode;
}

/**
 * Wraps children with a real StigmerProvider backed by a Connect transport.
 *
 * In preview mode, MSW intercepts all HTTP requests before they leave
 * the browser. The client is fully real -- same code path as production --
 * but the network layer is mocked. The fake API key is never sent to a
 * server; MSW handles the request at the service worker level.
 */
export function PreviewProviders({ children }: PreviewProvidersProps) {
  const client = useMemo(() => {
    const transport = createConnectTransport({
      baseUrl: "/",
      useBinaryFormat: false,
    });
    // The fake apiKey matters: without a credential, the provider's
    // registry hooks poll for a token every 500ms for 10 seconds on
    // every demo mount before their first fetch. With it, the fetches
    // fire immediately into the MSW fixtures.
    return new Stigmer({
      baseUrl: "/",
      apiKey: "scenar-preview",
      customTransport: transport,
    });
  }, []);

  return <StigmerProvider client={client}>{children}</StigmerProvider>;
}
